// Exa on the business's own key: the same calls `emplio web` makes on ours (../../../exa.ts), with every option,
// returned as data for scripts and automations; plus the rest of Exa's API (research tasks, websets, monitors,
// imports, webhooks) and every option of search/contents/answer, from its OpenAPI specs (actions.json,
// generated by `bun scripts/openapi-actions.ts exa`; COVERAGE.md says what's left out).
import { z } from "zod";
import { answer, CATEGORIES, ExaError, read, search, similar } from "../../../exa";
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { specActions } from "../openapi";

// Exa's errors as ours: a rejected key marks the connection for reconnecting
const run = async <T>(fn: () => Promise<T>) => {
  try {
    return await fn();
  } catch (error) {
    if (error instanceof ExaError) throw new AppsError(error.message, error.badKey);
    throw error;
  }
};

const n = z.number().int().min(1).max(100).default(10).describe("How many results (1-100, default 10)");
const text = z
  .number()
  .int()
  .min(100)
  .max(100_000)
  .optional()
  .describe("Each result's page text (markdown) up to this many characters, instead of the matching passages");

export const exa: OwnApp = {
  app: "exa",
  name: "Exa",
  logo: "/logos/exa.svg",
  keyField: {
    label: "API key",
    help: "From dashboard.exa.ai → API keys. Searches are billed to your Exa account.",
    placeholder: "xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx",
  },
  // the cheapest call that needs a valid key
  async check(key) {
    await run(() => read(key, ["https://example.com"], 100));
  },
  actions: {
    // websets' own server takes only x-api-key, so every call sends that
    ...(await specActions(new URL("./actions.json", import.meta.url), {
      name: "Exa",
      base: "https://api.exa.ai",
      tokenHelp: "dashboard.exa.ai/api-keys",
      auth: (key) => ({ "x-api-key": key }),
    })),
    search: {
      readOnly: true,
      description: "Search the web. Results come with the passages that match, or each page's text.",
      input: z.object({
        query: z.string().min(1).describe("What to find, in plain words; a description of the ideal page works best"),
        num_results: n,
        type: z.enum(["auto", "fast", "deep"]).default("auto").describe("fast: quickest; deep: slower and more thorough; auto: balanced"),
        category: z.enum(CATEGORIES).optional().describe("Only this kind of page"),
        include_domains: z.array(z.string()).optional().describe("Only these sites, e.g. [\"indiamart.com\"]"),
        exclude_domains: z.array(z.string()).optional().describe("Leave these sites out"),
        start_published_date: z.string().optional().describe("Published on or after, YYYY-MM-DD"),
        end_published_date: z.string().optional().describe("Published on or before, YYYY-MM-DD"),
        text_characters: text,
      }),
      run: (i, key) =>
        run(() =>
          search(key, {
            query: i.query,
            numResults: i.num_results,
            type: i.type,
            category: i.category,
            includeDomains: i.include_domains,
            excludeDomains: i.exclude_domains,
            startPublishedDate: i.start_published_date,
            endPublishedDate: i.end_published_date,
            textCharacters: i.text_characters,
          }),
        ),
    },
    get_contents: {
      readOnly: true,
      description: "Pages as clean text (markdown), by URL.",
      input: z.object({
        urls: z.array(z.string().url()).min(1).max(100).describe("The pages"),
        max_characters: z.number().int().min(100).max(200_000).default(50_000).describe("Most text per page (default 50,000)"),
        fresh: z.boolean().default(false).describe("Fetch them now instead of using Exa's copy (slower; for pages that change)"),
      }),
      run: (i, key) => run(() => read(key, i.urls, i.max_characters, i.fresh)),
    },
    find_similar: {
      readOnly: true,
      description: "Pages like a given one (other sites), e.g. competitors of a company's site.",
      input: z.object({ url: z.string().url().describe("The page to match"), num_results: n, text_characters: text }),
      run: (i, key) => run(() => similar(key, i.url, i.num_results, i.text_characters)),
    },
    answer: {
      readOnly: true,
      description: "A short answer to a question, researched on the web, with its sources.",
      input: z.object({ query: z.string().min(1).describe("The question") }),
      run: (i, key) => run(() => answer(key, i.query)),
    },
  },
};
